ALTER POLICY "Empresa pode ler mapas PDF" ON public.mapas_exploracao USING (empresa_id = public.minha_empresa() OR public.has_role(auth.uid(), 'superadmin'::public.app_role));
ALTER POLICY "Empresa pode enviar mapas PDF" ON public.mapas_exploracao WITH CHECK (empresa_id = public.minha_empresa() OR public.has_role(auth.uid(), 'superadmin'::public.app_role));
ALTER POLICY "Empresa pode atualizar mapas PDF" ON public.mapas_exploracao USING (empresa_id = public.minha_empresa() OR public.has_role(auth.uid(), 'superadmin'::public.app_role)) WITH CHECK (empresa_id = public.minha_empresa() OR public.has_role(auth.uid(), 'superadmin'::public.app_role));
ALTER POLICY "Empresa pode excluir mapas PDF" ON public.mapas_exploracao USING (empresa_id = public.minha_empresa() OR public.has_role(auth.uid(), 'superadmin'::public.app_role));
ALTER POLICY "Empresa pode ler arquivos de mapas" ON storage.objects USING (bucket_id = 'mapas-exploracao' AND ((storage.foldername(name))[1] = public.minha_empresa()::text OR public.has_role(auth.uid(), 'superadmin'::public.app_role)));
ALTER POLICY "Empresa pode enviar arquivos de mapas" ON storage.objects WITH CHECK (bucket_id = 'mapas-exploracao' AND ((storage.foldername(name))[1] = public.minha_empresa()::text OR public.has_role(auth.uid(), 'superadmin'::public.app_role)) AND storage.extension(name) = 'pdf');
ALTER POLICY "Empresa pode substituir arquivos de mapas" ON storage.objects USING (bucket_id = 'mapas-exploracao' AND ((storage.foldername(name))[1] = public.minha_empresa()::text OR public.has_role(auth.uid(), 'superadmin'::public.app_role))) WITH CHECK (bucket_id = 'mapas-exploracao' AND ((storage.foldername(name))[1] = public.minha_empresa()::text OR public.has_role(auth.uid(), 'superadmin'::public.app_role)) AND storage.extension(name) = 'pdf');
ALTER POLICY "Empresa pode excluir arquivos de mapas" ON storage.objects USING (bucket_id = 'mapas-exploracao' AND ((storage.foldername(name))[1] = public.minha_empresa()::text OR public.has_role(auth.uid(), 'superadmin'::public.app_role)));
ALTER TABLE public.mapas_exploracao DROP CONSTRAINT mapas_exploracao_tamanho_valido;
ALTER TABLE public.mapas_exploracao ADD CONSTRAINT mapas_exploracao_tamanho_valido CHECK (tamanho_bytes > 0 AND tamanho_bytes <= 104857600);